contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to send to addToBalance. The test call will send that much Ether.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // Read balance before the operation (from c's public getter and contract balance)
        uint beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // Perform the state-changing call, capturing whether it reverted.
        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values (always allowed even if call reverted)
        uint afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General rule: if addToBalance did not revert, the user's recorded balance and the contract's balance
        // must each increase by exactly 'amount'. If it reverted, neither observable should increase by amount.
        assert(
            (!reverted && afterUser == beforeUser + amount && afterContractBal == beforeContractBal + amount)
            || (reverted && afterUser == beforeUser && afterContractBal == beforeContractBal)
        );
    }

    // Allow receiving Ether so this contract can fund the test call
    receive() external payable {}
}

